/**
 * Map geometry and city centroids.
 *
 * Generated from Natural Earth public-domain data (ne_110m world countries, ne_10m Iranian
 * provinces), simplified and stored as SVG path strings in equirectangular lon/lat space.
 *
 * WHY THE GEOMETRY IS EMBEDDED RATHER THAN FETCHED FROM A TILE SERVER:
 * this platform is deployed inside utility networks that frequently have no internet route at all.
 * A Leaflet/Mapbox-style map would show an empty grey grid there. Embedding the outline keeps the
 * map working air-gapped, and removes a third-party request from an OT-adjacent application.
 *
 * LOCATION PRIVACY — the point of this file:
 * CITY_CENTROIDS holds CITY CENTRE coordinates. A city centre is public knowledge and is coarse:
 * it locates something to within tens of kilometres, which is the same granularity the rest of the
 * system already exposes (province + city). These are deliberately NOT site, substation or panel
 * positions — those live only in site_location_restricted and never reach the browser. A marker on
 * this map means "this city has N projects", never "the substation is here".
 */

export interface CityCentroid {
  cityId: string;
  lon: number;
  lat: number;
}

